import{_ as o,o as i,c as t,ae as a}from"./chunks/framework.qNV68s4p.js";const u=JSON.parse('{"title":"Usage","description":"","frontmatter":{},"headers":[],"relativePath":"guide/usage.md","filePath":"guide/usage.md","lastUpdated":1776332671000}'),l={name:"guide/usage.md"};function r(n,e,s,d,c,p){return i(),t("div",null,[...e[0]||(e[0]=[a('<h1 id="usage" tabindex="-1">Usage <a class="header-anchor" href="#usage" aria-label="Permalink to &quot;Usage&quot;">​</a></h1><p>This page gives a practical overview of how SweetEditor is typically used in a Compose Multiplatform application.</p><h2 id="core-concepts" tabindex="-1">Core Concepts <a class="header-anchor" href="#core-concepts" aria-label="Permalink to &quot;Core Concepts&quot;">​</a></h2><ul><li><code>SweetEditor</code>: the composable editor surface</li><li><code>SweetEditorController</code>: controller for editing, commands, providers, and runtime integration</li><li><code>EditorState</code>: editor state and platform bridge lifecycle</li><li><code>EditorDocument</code>: the active document bridge</li></ul><h2 id="typical-integration-flow" tabindex="-1">Typical Integration Flow <a class="header-anchor" href="#typical-integration-flow" aria-label="Permalink to &quot;Typical Integration Flow&quot;">​</a></h2><ol><li>Create or remember a <code>SweetEditorController</code></li><li>Load a document into the controller</li><li>Attach completion providers or decoration providers as needed</li><li>Render <code>SweetEditor</code></li><li>React to editor events through the controller event bus</li></ol><h2 id="common-extension-points" tabindex="-1">Common Extension Points <a class="header-anchor" href="#common-extension-points" aria-label="Permalink to &quot;Common Extension Points&quot;">​</a></h2><h3 id="decorations" tabindex="-1">Decorations <a class="header-anchor" href="#decorations" aria-label="Permalink to &quot;Decorations&quot;">​</a></h3><p>Use decoration providers to add:</p><ul><li>inlay hints</li><li>phantom text</li><li>diagnostics</li><li>gutter icons</li><li>fold regions</li><li>guides and highlights</li></ul><h3 id="completion" tabindex="-1">Completion <a class="header-anchor" href="#completion" aria-label="Permalink to &quot;Completion&quot;">​</a></h3><p>Completion providers can return:</p><ul><li>popup items</li><li>anchors</li><li>selection updates</li><li>custom item renderers</li></ul><h3 id="copilot-style-inline-suggestions" tabindex="-1">Copilot-style Inline Suggestions <a class="header-anchor" href="#copilot-style-inline-suggestions" aria-label="Permalink to &quot;Copilot-style Inline Suggestions&quot;">​</a></h3><p>SweetEditor also supports copilot-style inline suggestions in the Compose layer:</p><ul><li>show an <code>InlineSuggestion</code></li><li>render it as phantom text</li><li>accept with <code>Tab</code></li><li>dismiss with <code>Escape</code></li></ul><h2 id="related-guides" tabindex="-1">Related Guides <a class="header-anchor" href="#related-guides" aria-label="Permalink to &quot;Related Guides&quot;">​</a></h2><ul><li><a href="./theme-appearance">Theme / Appearance</a></li><li><a href="./api-cookbook">API Cookbook</a></li><li><a href="./decorations">Decorations</a></li><li><a href="./completion">Completion</a></li><li><a href="./copilot-inline-suggestion">Copilot / Inline Suggestion</a></li></ul><h2 id="example-modules" tabindex="-1">Example Modules <a class="header-anchor" href="#example-modules" aria-label="Permalink to &quot;Example Modules&quot;">​</a></h2><ul><li><a href="https://github.com/lumkit/SweetEditor-Compose/tree/main/example" target="_blank" rel="noreferrer">Example App</a></li><li><a href="https://github.com/lumkit/SweetEditor-Compose/tree/main/platform-demo" target="_blank" rel="noreferrer">Platform Demos</a></li></ul>',20)])])}const m=o(l,[["render",r]]);export{u as __pageData,m as default};
